 "content": "def transform(grid):
    """Replace masked 2s with the value in the matching 180-degree symmetric cell."""
    n = len(grid)
    m = len(grid[0])
    assert n == m
    out = [row[:] for row in grid]
    for r in range(n):
        for c in range(n):
            if grid[r][c] == 2:
                out[r][c] = grid[n - 1 - r][n - 1 - c]
    return out
